@php
    $property = $booking->property;
    $media = $property->media->firstWhere('is_primary', true) ?? $property->media->firstWhere('media_type', \App\Enums\PropertyMediaType::Image);
    $image = $media?->external_url ?: ($media?->storage_path ? '/storage/'.ltrim($media->storage_path, '/') : '/image.png');
    $status = $booking->status->value;
    $statusClass = match($status) {'confirmed', 'checked_in' => 'bg-emerald-100 text-emerald-800', 'cancelled' => 'bg-red-100 text-red-700', 'awaiting_payment' => 'bg-amber-100 text-amber-800', default => 'bg-slate-100 text-slate-700'};
    $nights = $booking->arrival_date->diffInDays($booking->departure_date);
    $payment = $booking->payments->sortByDesc('created_at')->first();
    $paid = (float)$booking->payments->filter(fn($p)=>$p->status->value==='completed' && $p->purpose->value!=='refund')->sum('amount');
    $refunded = (float)$booking->payments->filter(fn($p)=>$p->status->value==='completed' && $p->purpose->value==='refund')->sum('amount');
    $outstanding = max(0,(float)$booking->total_amount-$paid);
    $timezone = $booking->business?->timezone ?: 'Africa/Lagos';
    $checkInTime = $property->marketplaceListing?->check_in_time ?: '14:00';
    $checkInAt = \Carbon\CarbonImmutable::parse($booking->arrival_date->toDateString().' '.$checkInTime, $timezone);
    $isRefundable = now($timezone)->lt($checkInAt->copy()->subHours(48));
    $review = $booking->reviews->first();
    $reviewInvitation = $booking->reviewInvitations->first();
    $reviewInvitationExpired = $reviewInvitation?->expires_at?->isPast() ?? false;
@endphp
